import { SQSClient, SendMessageCommand } from '@aws-sdk/client-sqs';

const client = new SQSClient({ region: 'us-east-1' });

const command = new SendMessageCommand({
  QueueUrl: 'https://sqs.us-east-1.amazonaws.com/123456789012/orders.fifo',
  MessageBody: JSON.stringify({ orderId: 101, product: 'Laptop' }),
  MessageDeduplicationId: 'order-101-1',
  MessageGroupId: 'order-101'
});

const response = await client.send(command);
console.log('Message sent, ID:', response.MessageId);
